import java.util.*;
class ListWalkA {
  int count(List<List<Integer>> links, int root) {
    Set<Integer> done = new HashSet<>();
    Queue<Integer> frontier = new ArrayDeque<>();
    done.add(root); frontier.offer(root); int total = 0;
    while (!frontier.isEmpty()) {
      int u = frontier.poll(); total++;
      for (int v : links.get(u)) if (done.add(v)) frontier.offer(v);
    }
    return total;
  }
}

import java.util.*;
class ListWalkB {
  int count(List<List<Integer>> edges, int source) {
    boolean[] marked = new boolean[edges.size()];
    Deque<Integer> todo = new ArrayDeque<>();
    marked[source] = true; todo.addLast(source); int total = 0;
    while (!todo.isEmpty()) {
      int current = todo.removeFirst(); total++;
      for (int next : edges.get(current)) {
        if (!marked[next]) { marked[next] = true; todo.addLast(next); }
      }
    }
    return total;
  }
}

import java.util.*;
class MultiListWalk {
  void spread(Map<Integer,List<Integer>> links, List<Integer> starts) {
    Set<Integer> seen = new HashSet<>();
    Deque<Integer> work = new ArrayDeque<>();
    for (int seed : starts) if (seen.add(seed)) work.add(seed);
    while (!work.isEmpty()) {
      int here = work.remove();
      for (int there : links.get(here)) if (seen.add(there)) work.add(there);
    }
  }
}

import java.util.*;
class MatrixWalk {
  int count(boolean[][] arcs, int origin) {
    int n = arcs.length; boolean[] seen = new boolean[n];
    Queue<Integer> q = new ArrayDeque<>(); seen[origin] = true; q.add(origin);
    int result = 0;
    while (!q.isEmpty()) {
      int u = q.remove(); result++;
      for (int v = 0; v < n; v++)
        if (arcs[u][v] && !seen[v]) { seen[v] = true; q.add(v); }
    }
    return result;
  }
}

import java.util.*;
class RepeatedListWalk {
  void all(List<List<Integer>> links) {
    int n = links.size();
    for (int start = 0; start < n; start++) {
      Set<Integer> seen = new HashSet<>(); Queue<Integer> q = new ArrayDeque<>();
      seen.add(start); q.add(start);
      while (!q.isEmpty()) {
        int u = q.remove();
        for (int v : links.get(u)) if (seen.add(v)) q.add(v);
      }
    }
  }
}

import java.util.*;
class UnboundedListWalk {
  void walk(List<List<Integer>> links, int start) {
    Queue<Integer> q = new ArrayDeque<>(); q.add(start);
    while (!q.isEmpty()) {
      int u = q.remove();
      for (int v : links.get(u)) q.add(v);
    }
  }
}

import java.util.*;
class HiddenNeighbors {
  interface Network { Iterable<Integer> neighborsOf(int v); }
  void walk(Network net, int source, int n) {
    boolean[] seen = new boolean[n]; Queue<Integer> q = new ArrayDeque<>();
    seen[source] = true; q.add(source);
    while (!q.isEmpty()) {
      int u = q.remove();
      for (int v : net.neighborsOf(u)) if (!seen[v]) { seen[v] = true; q.add(v); }
    }
  }
}

import java.util.*;
class GridFourA {
  void fill(int[][] board, int rows, int cols, int sr, int sc) {
    boolean[][] seen = new boolean[rows][cols]; int[] dr = {-1,1,0,0}; int[] dc = {0,0,-1,1};
    Queue<int[]> q = new ArrayDeque<>(); seen[sr][sc] = true; q.add(new int[]{sr,sc});
    while (!q.isEmpty()) {
      int[] cell = q.remove();
      for (int d = 0; d < 4; d++) {
        int nr = cell[0] + dr[d], nc = cell[1] + dc[d];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] == 1 && !seen[nr][nc]) {
          seen[nr][nc] = true; q.add(new int[]{nr,nc});
        }
      }
    }
  }
}

import java.util.*;
class GridEightB {
  void traverse(int[][] terrain, int height, int width, int y, int x) {
    boolean[][] visited = new boolean[height][width];
    int[] dy = {-1,-1,-1,0,0,1,1,1}; int[] dx = {-1,0,1,-1,1,-1,0,1};
    Queue<int[]> pending = new ArrayDeque<>(); visited[y][x] = true; pending.add(new int[]{y,x});
    while (!pending.isEmpty()) {
      int[] p = pending.remove();
      for (int k = 0; k < 8; k++) {
        int yy = p[0] + dy[k], xx = p[1] + dx[k];
        if (yy >= 0 && yy < height && xx >= 0 && xx < width && terrain[yy][xx] != 0 && !visited[yy][xx]) {
          visited[yy][xx] = true; pending.add(new int[]{yy,xx});
        }
      }
    }
  }
}

