import java.util.*;
class QueueDrain {
  int total(List<Integer> values) {
    Queue<Integer> q = new ArrayDeque<>(values); int sum = 0;
    while (!q.isEmpty()) sum += q.remove();
    return sum;
  }
}

from collections import deque

def reach_count(adjacency, origin):
    seen = {origin}
    pending = deque([origin])
    count = 0
    while pending:
        vertex = pending.popleft()
        count += 1
        for neighbor in adjacency[vertex]:
            if neighbor not in seen:
                seen.add(neighbor)
                pending.append(neighbor)
    return count

from collections import deque

def spread(adjacency, sources):
    seen = set(sources)
    queue = deque(sources)
    while queue:
        current = queue.popleft()
        for nxt in adjacency[current]:
            if nxt not in seen:
                seen.add(nxt)
                queue.append(nxt)
    return seen

from collections import deque

def reachable(adjacency, start):
    queue = deque([start])
    visited = set()
    while queue:
        node = queue.popleft()
        if node in visited:
            continue
        visited.add(node)
        for neighbor in adjacency[node]:
            queue.append(neighbor)
    return visited

