def matrix_reachable(matrix, source):
    n = len(matrix)
    seen = {source}
    q = deque([source])
    while q:
        node = q.popleft()
        for candidate in range(n):
            if matrix[node][candidate] and candidate not in seen:
                seen.add(candidate)
                q.append(candidate)
    return seen

