def all_reachable(adjacency):
    n = len(adjacency)
    results = []
    for source in range(n):
        seen = {source}
        queue = deque([source])
        while queue:
            node = queue.popleft()
            for neighbor in adjacency[node]:
                if neighbor not in seen:
                    seen.add(neighbor)
                    queue.append(neighbor)
        results.append(seen)
    return results

