def island_sizes(board):
    rows = len(board)
    cols = len(board[0])
    seen = set()
    sizes = []
    for y in range(rows):
        for x in range(cols):
            if board[y][x] != "#" or (y, x) in seen:
                continue
            queue = deque([(y, x)])
            seen.add((y, x))
            size = 0
            while queue:
                cy, cx = queue.popleft()
                size += 1
                for ny, nx in ((cy-1,cx),(cy+1,cx),(cy,cx-1),(cy,cx+1)):
                    if 0 <= ny < rows and 0 <= nx < cols and board[ny][nx] == "#" and (ny,nx) not in seen:
                        seen.add((ny, nx))
                        queue.append((ny, nx))
            sizes.append(size)
    return sizes

