def adjacent(r, c):
    return ((r-1,c),(r+1,c),(r,c-1),(r,c+1))

def flood(grid, start):
    rows, cols = len(grid), len(grid[0])
    seen = {start}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        for rr, cc in adjacent(r, c):
            if 0 <= rr < rows and 0 <= cc < cols and grid[rr][cc] and (rr,cc) not in seen:
                seen.add((rr,cc))
                queue.append((rr,cc))

